{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://lastking.local/schemas/config-change-audit.schema.json",
  "title": "Lastking Config Change Audit Record Schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "actor",
    "timestamp",
    "file",
    "change_summary",
    "writer_source"
  ],
  "properties": {
    "actor": {
      "type": "string",
      "minLength": 1,
      "maxLength": 100,
      "pattern": "^[A-Za-z0-9._@\\-]+$",
      "description": "Who made the configuration change"
    },
    "timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "UTC ISO-8601 timestamp"
    },
    "file": {
      "type": "string",
      "minLength": 1,
      "maxLength": 260,
      "description": "Relative file path changed"
    },
    "change_summary": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "description": "One-line summary of what changed"
    },
    "review_status": {
      "type": "string",
      "enum": [
        "pending",
        "approved",
        "rejected"
      ]
    },
    "reviewer": {
      "type": "string",
      "maxLength": 100
    },
    "reviewed_at": {
      "type": "string",
      "format": "date-time"
    },
    "branch": {
      "type": "string",
      "maxLength": 120
    },
    "commit": {
      "type": "string",
      "pattern": "^[a-fA-F0-9]{7,40}$"
    },
    "impact_scope": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "difficulty",
          "spawn",
          "enemy",
          "reward",
          "economy",
          "other"
        ]
      },
      "uniqueItems": true
    },
    "linked_kpi": {
      "type": "array",
      "items": {
        "type": "string",
        "maxLength": 80
      },
      "uniqueItems": true
    },
    "notes": {
      "type": "string",
      "maxLength": 1000
    },
    "writer_source": {
      "type": "string",
      "const": "script-only",
      "description": "Audit record must be generated by script-only pipeline."
    }
  },
  "allOf": [
    {
      "if": {
        "required": [
          "review_status"
        ],
        "properties": {
          "review_status": {
            "const": "approved"
          }
        }
      },
      "then": {
        "required": [
          "reviewer",
          "reviewed_at"
        ]
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://lastking.local/schemas/difficulty-config.schema.json",
  "title": "Lastking Difficulty Config Schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "mode",
    "default_level_id",
    "rounding_policy",
    "allow_cross_tier_skip",
    "unlock_policy",
    "levels"
  ],
  "properties": {
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Semantic version of difficulty config"
    },
    "mode": {
      "type": "string",
      "enum": [
        "numeric-only"
      ],
      "description": "v1 locks difficulty changes to numeric multipliers only"
    },
    "default_level_id": {
      "type": "string",
      "pattern": "^[a-z0-9_\\-]+$"
    },
    "rounding_policy": {
      "type": "string",
      "enum": [
        "floor"
      ],
      "description": "Integer-only pipeline: percentage calculation rounds down"
    },
    "levels": {
      "type": "array",
      "minItems": 10,
      "description": "Supports 10+ difficulty levels",
      "items": {
        "$ref": "#/$defs/difficultyLevel"
      }
    },
    "unlock_policy": {
      "type": "string",
      "enum": [
        "clear-to-unlock-config-driven"
      ],
      "description": "Difficulty unlock policy is config-driven clear-to-unlock."
    },
    "allow_cross_tier_skip": {
      "type": "boolean",
      "const": false,
      "description": "Cross-tier unlock skip is disallowed by lock."
    }
  },
  "$defs": {
    "difficultyLevel": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "order",
        "display_name_key",
        "enemy_hp_mult",
        "enemy_dmg_mult",
        "budget_mult_normal",
        "budget_mult_elite",
        "budget_mult_boss",
        "resource_mult"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z0-9_\\-]+$"
        },
        "order": {
          "type": "integer",
          "minimum": 1,
          "description": "Ascending order used by UI and progression"
        },
        "display_name_key": {
          "type": "string",
          "pattern": "^[A-Z0-9_\\.]+$",
          "description": "Localization key for bilingual UI"
        },
        "enemy_hp_mult": {
          "type": "integer",
          "minimum": 1,
          "description": "Percent multiplier (e.g. 100 = 1.00x)"
        },
        "enemy_dmg_mult": {
          "type": "integer",
          "minimum": 1,
          "description": "Percent multiplier (e.g. 100 = 1.00x)"
        },
        "resource_mult": {
          "type": "integer",
          "minimum": 1,
          "description": "Percent multiplier applied to economy income"
        },
        "notes": {
          "type": "string",
          "maxLength": 200
        },
        "budget_mult_normal": {
          "type": "integer",
          "minimum": 1,
          "description": "Percent multiplier applied to normal channel budget"
        },
        "budget_mult_elite": {
          "type": "integer",
          "minimum": 1,
          "description": "Percent multiplier applied to elite channel budget"
        },
        "budget_mult_boss": {
          "type": "integer",
          "minimum": 1,
          "description": "Percent multiplier applied to boss channel budget"
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://lastking.local/schemas/enemy-config.schema.json",
  "title": "Lastking Enemy Config Schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "seed_policy",
    "enemies"
  ],
  "properties": {
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Semantic version of enemy config"
    },
    "seed_policy": {
      "type": "string",
      "enum": [
        "deterministic"
      ],
      "description": "Must stay deterministic to support reproducible seeded spawn"
    },
    "enemies": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/enemy"
      }
    }
  },
  "$defs": {
    "enemy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "cost",
        "hp",
        "dmg",
        "move_speed",
        "range",
        "attack_interval",
        "armor",
        "tags",
        "spawn_weight",
        "min_day",
        "max_day",
        "is_elite",
        "is_boss"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z0-9_\\-]+$"
        },
        "cost": {
          "type": "integer",
          "minimum": 1,
          "description": "Budget cost"
        },
        "hp": {
          "type": "integer",
          "minimum": 1
        },
        "dmg": {
          "type": "integer",
          "minimum": 0
        },
        "move_speed": {
          "type": "integer",
          "minimum": 1,
          "description": "Fixed-point speed unit (e.g. milli-tile/second), integer-only"
        },
        "range": {
          "type": "integer",
          "minimum": 0,
          "description": "Fixed-point attack range, integer-only"
        },
        "attack_interval": {
          "type": "integer",
          "minimum": 1,
          "description": "Attack interval in milliseconds"
        },
        "armor": {
          "type": "integer",
          "minimum": 0
        },
        "tags": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": [
              "base",
              "fast",
              "armored",
              "ranged",
              "self_destruct",
              "elite",
              "boss"
            ]
          }
        },
        "spawn_weight": {
          "type": "integer",
          "minimum": 0,
          "description": "Used in seeded weighted pick inside Top-K"
        },
        "min_day": {
          "type": "integer",
          "minimum": 1,
          "maximum": 15
        },
        "max_day": {
          "type": "integer",
          "minimum": 1,
          "maximum": 15
        },
        "is_elite": {
          "type": "boolean"
        },
        "is_boss": {
          "type": "boolean"
        },
        "lane_ratio_override": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "left",
            "right"
          ],
          "properties": {
            "left": {
              "type": "integer",
              "minimum": 0,
              "maximum": 100
            },
            "right": {
              "type": "integer",
              "minimum": 0,
              "maximum": 100
            }
          },
          "description": "Optional lane split override for specific enemy"
        },
        "night_type_mask": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": [
              "normal",
              "elite",
              "boss"
            ]
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "is_boss": {
                "const": true
              }
            }
          },
          "then": {
            "properties": {
              "tags": {
                "contains": {
                  "const": "boss"
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "is_elite": {
                "const": true
              }
            }
          },
          "then": {
            "properties": {
              "tags": {
                "contains": {
                  "const": "elite"
                }
              }
            }
          }
        }
      ]
    }
  }
}

