        "spawn_count_p",
        "castle_damage_p",
        "blocked_path_p",
        "elite_boss_p",
        "final_score"
      ],
      "properties": {
        "budget_p": {
          "type": "string",
          "const": "floor(100 * normal_budget_used / normal_budget_ref_day)"
        },
        "spawn_count_p": {
          "type": "string",
          "const": "floor(100 * spawned_count / spawned_ref_day)"
        },
        "castle_damage_p": {
          "type": "string",
          "const": "floor(100 * castle_damage / castle_max_hp)"
        },
        "blocked_path_p": {
          "type": "string",
          "const": "floor(100 * blocked_seconds / night_seconds)"
        },
        "elite_boss_p": {
          "type": "string",
          "const": "clamp(base_by_night + min(20, elite_spawned*2 + boss_spawned*10), 0, 100)"
        },
        "final_score": {
          "type": "string",
          "const": "(35*budget_p + 25*spawn_count_p + 20*castle_damage_p + 10*blocked_path_p + 10*elite_boss_p)/100"
        }
      }
    },
    "base_by_night": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "normal",
        "elite",
        "boss"
      ],
      "properties": {
        "normal": {
          "type": "integer",
          "const": 10
        },
        "elite": {
          "type": "integer",
          "const": 60
        },
        "boss": {
          "type": "integer",
          "const": 70
        }
      }
    },
    "elite_boss_component": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "elite_multiplier",
        "boss_multiplier",
        "dynamic_cap"
      ],
      "properties": {
        "elite_multiplier": {
          "type": "integer",
          "const": 2
        },
        "boss_multiplier": {
          "type": "integer",
          "const": 10
        },
        "dynamic_cap": {
          "type": "integer",
          "const": 20
        }
      }
    },
    "reference_metrics": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "normal_budget_ref_day",
        "spawned_ref_day"
      ],
      "properties": {
        "normal_budget_ref_day": {
          "$ref": "#/$defs/daySeries",
          "description": "Locked baseline series for normal budget reference by day index"
        },
        "spawned_ref_day": {
          "$ref": "#/$defs/daySeries",
          "description": "Locked baseline series for spawned unit reference by day index"
        }
      },
      "description": "Two baseline references are mandatory and cannot be omitted"
    }
  },
  "$defs": {
